import {createHash} from 'node:crypto';import {mockAtlas,atlasCatalog,atlasBeaches,atlasContours} from './nextjs-atlas.mjs';
export async function mockOfflineNavigation(page,base,{atlas=true}={}){if(atlas)await mockAtlas(page,base);let revision=1,offline=false,failUpdate=false;const requests=[];const contents=version=>{const catalog=structuredClone(atlasCatalog);catalog.updated_at='offline-'+version;if(version===2)catalog.regions[1].name='Updated Second Bay';return {'beaches.json':atlasBeaches,'data/catalog.json':catalog,'data/example-bay-contours.json':atlasContours,'data/second-bay-contours.json':version===1?atlasContours:{...atlasContours,features:atlasContours.features.map(f=>({...f,properties:{...f.properties,depth_m:f.properties.depth_m===20?30:f.properties.depth_m}}))},'guides.json':{},'social.json':{posts:[]},'data/beach-summaries.json':{beaches:[]}};};const manifest=version=>{const values=contents(version),files=Object.fromEntries(Object.entries(values).map(([path,data])=>{const body=JSON.stringify(data);return [path,{hash:createHash('sha256').update(body).digest('hex'),bytes:Buffer.byteLength(body),label:path}];}));return {version:1,revision:String(version),files,regions:Object.fromEntries(atlasCatalog.regions.map(region=>{const paths=['beaches.json','data/catalog.json',region.contour_file,'guides.json','social.json','data/beach-summaries.json'];return [region.id,{name:region.name,files:paths,bytes:paths.reduce((n,path)=>n+files[path].bytes,0)}];}))};};await page.route('**/*',async route=>{const path=new URL(route.request().url()).pathname.slice(1);if(path==='data/downloads.json'||path in contents(revision)){requests.push({path,offline,revision});if(offline)return route.abort('internetdisconnected');if(path==='data/downloads.json')return route.fulfill({json:manifest(revision)});if(failUpdate&&revision===2&&path==='data/second-bay-contours.json')return route.fulfill({status:503,json:{error:'Synthetic interrupted update'}});return route.fulfill({json:contents(revision)[path]});}return route.fallback();});return {requests,setRevision:value=>revision=value,setOffline:value=>offline=value,failUpdate:value=>failUpdate=value};}
